export const toPoint = (r: IspRow): Point => {
  const { up, down, mid } = r
  if (up != null && down != null) return { t: r.t, p: Math.max(up, mid ?? up), p2: Math.min(down, mid ?? down) }
  const p = up ?? down ?? mid!
  return { t: r.t, p, p2: p }
}

